'use strict';

// MODULES //

var setReadOnly = require( '@stdlib/utils/define-nonenumerable-read-only-property' );
var factory = require( './factory.js' );


// MAIN //

/**
* Creates a xorshift32 pseudorandom number generator.
*
* @param {Options} [options] - options
* @param {PRNGSeedUint32} [options.seed] - pseudorandom number generator seed
* @param {PRNGStateXorshift32} [options.state] - pseudorandom number generator state
* @param {boolean} [options.copy=true] - boolean indicating whether to copy a provided pseudorandom number generator state
* @returns {PRNG} xorshift32 PRNG
*
* @example
* var xorshift32 = require( '@stdlib/random/base/xorshift32' );
*
* // Use the default PRNG:
* var v = xorshift32();
* // returns <number>
*
* @example
* var xorshift32 = require( '@stdlib/random/base/xorshift32' );
*
* // Create a new PRNG with custom seed:
* var prng = xorshift32({
*     'seed': 1234
* });
*
* var v = prng();
* // returns <number>
*/

// Create a default instance for property access
var defaultInstance = factory();

/**
* Generates pseudorandom numbers using a default xorshift32 generator or.
* creates a new generator when provided with options.
*
* @param {Options} [options] - options
* @returns {(number|PRNG)} random number or PRNG
*/
function xorshift32( options ) {
	if ( arguments.length === 0 ) {
		// No arguments: return a random number from default instance
		return defaultInstance();
	}
	// With arguments: return a new PRNG created by factory
	return factory( options );
}

// Attach all properties and methods from the default instance to the factory
setReadOnly( xorshift32, 'NAME', defaultInstance.NAME );
setReadOnly( xorshift32, 'seed', defaultInstance.seed );
setReadOnly( xorshift32, 'seedLength', defaultInstance.seedLength );
setReadOnly( xorshift32, 'state', defaultInstance.state );
setReadOnly( xorshift32, 'stateLength', defaultInstance.stateLength );
setReadOnly( xorshift32, 'byteLength', defaultInstance.byteLength );
setReadOnly( xorshift32, 'toJSON', defaultInstance.toJSON );
setReadOnly( xorshift32, 'MIN', defaultInstance.MIN );
setReadOnly( xorshift32, 'MAX', defaultInstance.MAX );
setReadOnly( xorshift32, 'normalized', defaultInstance.normalized );

// Attach properties and methods from the default instance to the default instance itself
setReadOnly( xorshift32, 'factory', factory );


// EXPORTS //

module.exports = xorshift32;
